let mut next = [[b'.'; 8]; 8];
for r in 0..8 {
    for c in 0..8 {
        let mut neighbors = 0;
        for dr in -1..=1 {
            for dc in -1..=1 {
                let rr = r as i32 + dr;
                let cc = c as i32 + dc;
                if (dr != 0 || dc != 0)
                    && (0..8).contains(&rr)
                    && (0..8).contains(&cc)
                    && board[rr as usize][cc as usize] == b'#'
                {
                    neighbors += 1;
                }
            }
        }
        if neighbors == 3 || (board[r][c] == b'#' && neighbors == 2) {
            next[r][c] = b'#';
        }
    }
}
board = next;
